#include <deque>
#include <iostream>
#include <vector>
#include <algorithm>

static void report(const char* name,
                   const std::vector<int>& comp,
                   const std::vector<int>& arrival,
                   const std::vector<int>& burst)
{
    const std::size_t n{ comp.size() };

    std::cout << name << " completion";
    for (std::size_t i = 0; i < n; ++i) std::cout << ' ' << comp[i];
    std::cout << "\n";

    std::cout << name << " turnaround";
    for (std::size_t i = 0; i < n; ++i) std::cout << ' ' << (comp[i] - arrival[i]);
    std::cout << "\n";

    std::cout << name << " waiting";
    for (std::size_t i = 0; i < n; ++i) std::cout << ' ' << (comp[i] - arrival[i] - burst[i]);
    std::cout << "\n";
}

int main()
{
    int quantum{};
    int n{};
    if (!(std::cin >> quantum >> n)) return 0;

    std::vector<int> arrival(static_cast<std::size_t>(n < 0 ? 0 : n));
    std::vector<int> burst(arrival.size());
    for (std::size_t i = 0; i < arrival.size(); ++i)
        std::cin >> arrival[i] >> burst[i];

    const std::size_t N{ arrival.size() };

    /* ---------------- FCFS ---------------- */
    {
        std::vector<std::size_t> order(N);
        for (std::size_t i = 0; i < N; ++i) order[i] = i;
        std::sort(order.begin(), order.end(), [&](std::size_t a, std::size_t b) {
            if (arrival[a] != arrival[b]) return arrival[a] < arrival[b];
            return a < b;
        });

        std::vector<int> comp(N, 0);
        int t{ 0 };
        for (std::size_t i : order)
        {
            if (t < arrival[i]) t = arrival[i];
            t += burst[i];
            comp[i] = t;
        }
        report("fcfs", comp, arrival, burst);
    }

    /* ---------------- SJF, non-preemptive ---------------- */
    {
        std::vector<bool> done(N, false);
        std::vector<int> comp(N, 0);
        int t{ 0 };
        for (std::size_t k = 0; k < N; ++k)
        {
            /* Nothing has arrived yet: jump to the next arrival. */
            bool any{ false };
            for (std::size_t i = 0; i < N; ++i)
                if (!done[i] && arrival[i] <= t) { any = true; break; }
            if (!any)
            {
                int soonest{ 0 };
                bool first{ true };
                for (std::size_t i = 0; i < N; ++i)
                    if (!done[i] && (first || arrival[i] < soonest)) { soonest = arrival[i]; first = false; }
                t = soonest;
            }

            std::size_t pick{ 0 };
            bool have{ false };
            for (std::size_t i = 0; i < N; ++i)
            {
                if (done[i] || arrival[i] > t) continue;
                if (!have) { pick = i; have = true; continue; }
                if (burst[i] < burst[pick]) pick = i;
                else if (burst[i] == burst[pick] && arrival[i] < arrival[pick]) pick = i;
            }
            t += burst[pick];
            comp[pick] = t;
            done[pick] = true;
        }
        report("sjf", comp, arrival, burst);
    }

    /* ---------------- Round robin ---------------- */
    {
        std::vector<int> rem(burst);
        std::vector<int> comp(N, 0);
        std::vector<bool> admitted(N, false);
        std::deque<std::size_t> q;
        int t{ 0 };
        long long running{ -1 };
        int qleft{ 0 };
        std::size_t finished{ 0 };

        auto admit = [&](int now) {
            for (std::size_t i = 0; i < N; ++i)
                if (!admitted[i] && arrival[i] == now) { admitted[i] = true; q.push_back(i); }
        };

        admit(0);
        while (finished < N)
        {
            if (running < 0)
            {
                if (!q.empty()) { running = static_cast<long long>(q.front()); q.pop_front(); qleft = quantum; }
                else { ++t; admit(t); continue; }
            }
            const std::size_t r{ static_cast<std::size_t>(running) };
            --rem[r];
            --qleft;
            ++t;
            admit(t);                       /* arrivals go in ahead of a preempted process */
            if (rem[r] == 0) { comp[r] = t; ++finished; running = -1; }
            else if (qleft == 0) { q.push_back(r); running = -1; }
        }
        report("rr", comp, arrival, burst);
    }

    return 0;
}
